56	// The listing shows the device's own uploads and the uploads it was granted
57	// read access to, side by side, each once, in creation order, with the full
58	// metadata, the owned marker and the ascending chunk progress.
59	func TestListAttachmentsContract(t *testing.T) {
60		h, _ := newTestHandler(t)
61		registerDevice(t, h, "dev-1")
62		registerDevice(t, h, "dev-2")
63		registerDevice(t, h, "dev-3")
64	
65		// dev-1 creates two uploads; dev-2 creates one and grants dev-1 read
66		// access. dev-3 has nothing visible at all.
67		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("hello world"), 4)
68		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
69		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
70		mustCreateAttachment(t, h, "dev-2", "att-2", []byte("shared content"), 8)
71		putChunk(t, h, "dev-2", "att-2", 0, []byte("shared c"))
72		putChunk(t, h, "dev-2", "att-2", 1, []byte("ontent"))
73		if w, body := completeAttachment(t, h, "dev-2", "att-2"); w.Code != http.StatusOK || body["complete"] != true {
74			t.Fatalf("complete att-2 = %d %v", w.Code, body)
75		}
76		mustCreateAttachment(t, h, "dev-1", "att-3", []byte("data"), 2)
77		setAccess(t, h, "dev-2", "att-2", "dev-1", "grant")
78	
79		w, items := getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
80		if w.Code != http.StatusOK {
81			t.Fatalf("list = %d body=%s", w.Code, w.Body.String())
82		}
83		if got := listIDs(items); !equalStrings(got, []string{"att-1", "att-2", "att-3"}) {
84			t.Fatalf("list order = %v, want [att-1 att-2 att-3]", got)
85		}
86	
87		// Own upload: owned=true, metadata and ascending progress.
88		if items[0]["owned"] != true ||
89			items[0]["totalBytes"] != float64(11) ||
90			items[0]["chunkSize"] != float64(4) ||
91			items[0]["sha256"] != sha256Hex([]byte("hello world")) ||
92			items[0]["complete"] != false ||
93			fmt.Sprint(items[0]["receivedChunks"]) != "[0 2]" {
94			t.Fatalf("own entry = %v", items[0])
95		}
96		// Granted upload: owned=false, same metadata the creator sees, sealed.
97		if items[1]["owned"] != false ||
98			items[1]["totalBytes"] != float64(14) ||
99			items[1]["chunkSize"] != float64(8) ||
100			items[1]["sha256"] != sha256Hex([]byte("shared content")) ||
101			items[1]["complete"] != true ||
102			fmt.Sprint(items[1]["receivedChunks"]) != "[0 1]" {
103			t.Fatalf("granted entry = %v", items[1])
104		}
105		// Fresh upload with no chunks yet: an empty (non-null) progress array.
106		if items[2]["owned"] != true || fmt.Sprint(items[2]["receivedChunks"]) != "[]" {
107			t.Fatalf("empty-progress entry = %v", items[2])
108		}
109		if !strings.Contains(w.Body.String(), `"receivedChunks":[]`) {
110			t.Fatalf("empty progress must serialize as []: %s", w.Body.String())
111		}
112	
113		// The creator of the granted attachment lists it as its own.
114		w, items = getAttachmentList(t, h, "/v1/devices/dev-2/attachments")
115		if w.Code != http.StatusOK || !equalStrings(listIDs(items), []string{"att-2"}) || items[0]["owned"] != true {
116			t.Fatalf("creator list = %d %v", w.Code, items)
117		}
118	
119		// A device with nothing visible gets an empty (non-null) array.
120		w, items = getAttachmentList(t, h, "/v1/devices/dev-3/attachments")
121		if w.Code != http.StatusOK || len(items) != 0 {
122			t.Fatalf("empty list = %d %v", w.Code, items)
123		}
124		if !strings.Contains(w.Body.String(), `"attachments":[]`) {
125			t.Fatalf("empty list body = %s", w.Body.String())
126		}
127	
128		// A grant to the creator itself must not duplicate the entry.
129		setAccess(t, h, "dev-1", "att-1", "dev-1", "grant")
130		_, items = getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
131		if got := listIDs(items); !equalStrings(got, []string{"att-1", "att-2", "att-3"}) {
132			t.Fatalf("list after self-grant = %v, want each attachment once", got)
133		}
134	}
