136	// Pagination: limit/offset page the stable creation order; with no
137	// intervening create or delete the pages neither repeat nor skip an entry.
138	func TestListAttachmentsPagination(t *testing.T) {
139		h, _ := newTestHandler(t)
140		registerDevice(t, h, "dev-1")
141		registerDevice(t, h, "dev-2")
142		for i, id := range []string{"att-1", "att-2", "att-3", "att-4", "att-5"} {
143			mustCreateAttachment(t, h, "dev-1", id, []byte("x"), 1)
144			_ = i
145		}
146		// One granted attachment from another device sorts by its own creation
147		// time: it was created after att-5, so it pages last.
148		mustCreateAttachment(t, h, "dev-2", "att-6", []byte("y"), 1)
149		setAccess(t, h, "dev-2", "att-6", "dev-1", "grant")
150	
151		// Default limit is 100: one page holds everything, in creation order.
152		_, items := getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
153		if got := listIDs(items); !equalStrings(got, []string{"att-1", "att-2", "att-3", "att-4", "att-5", "att-6"}) {
154			t.Fatalf("default page = %v", got)
155		}
156	
157		// Walk the list in pages of two: no duplicates, no gaps.
158		var seen []string
159		for offset := 0; offset < 6; offset += 2 {
160			_, page := getAttachmentList(t, h, fmt.Sprintf("/v1/devices/dev-1/attachments?limit=2&offset=%d", offset))
161			if len(page) != 2 {
162				t.Fatalf("page at offset %d has %d entries, want 2", offset, len(page))
163			}
164			seen = append(seen, listIDs(page)...)
165		}
166		if !equalStrings(seen, []string{"att-1", "att-2", "att-3", "att-4", "att-5", "att-6"}) {
167			t.Fatalf("paged walk = %v", seen)
168		}
169	
170		// A partial last page and a page past the end.
171		_, page := getAttachmentList(t, h, "/v1/devices/dev-1/attachments?limit=4&offset=4")
172		if got := listIDs(page); !equalStrings(got, []string{"att-5", "att-6"}) {
173			t.Fatalf("last partial page = %v", got)
174		}
175		w, page := getAttachmentList(t, h, "/v1/devices/dev-1/attachments?offset=6")
176		if w.Code != http.StatusOK || len(page) != 0 {
177			t.Fatalf("page past end = %d %v", w.Code, page)
178		}
179	
180		// limit=1 and limit=1000 are both accepted bounds.
181		if w, _ := getAttachmentList(t, h, "/v1/devices/dev-1/attachments?limit=1"); w.Code != http.StatusOK {
182			t.Fatalf("limit=1 = %d", w.Code)
183		}
184		if w, _ := getAttachmentList(t, h, "/v1/devices/dev-1/attachments?limit=1000"); w.Code != http.StatusOK {
185			t.Fatalf("limit=1000 = %d", w.Code)
186		}
187	}
