189	// Illegal pagination parameters are a 400 JSON error; an unregistered device
190	// is a 404 JSON error with no listing. Parameter shape is checked first.
191	func TestListAttachmentsRejectsBadParams(t *testing.T) {
192		h, _ := newTestHandler(t)
193		registerDevice(t, h, "dev-1")
194		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("x"), 1)
195	
196		for _, query := range []string{
197			"limit=0", "limit=-1", "limit=1001", "limit=x", "limit=1.5",
198			"offset=-1", "offset=x", "offset=1.5",
199		} {
200			r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments?"+query, nil)
201			w := serveRecorder(h, r)
202			if w.Code != http.StatusBadRequest {
203				t.Fatalf("?%s = %d, want 400 body=%s", query, w.Code, w.Body.String())
204			}
205			assertJSONError(t, w)
206		}
207	
208		// Unregistered device: 404 JSON, no listing content.
209		r := httptest.NewRequest(http.MethodGet, "/v1/devices/ghost/attachments", nil)
210		w := serveRecorder(h, r)
211		if w.Code != http.StatusNotFound {
212			t.Fatalf("unknown device = %d, want 404", w.Code)
213		}
214		assertJSONError(t, w)
215		if strings.Contains(w.Body.String(), "att-1") || strings.Contains(w.Body.String(), "attachments") {
216			t.Fatalf("404 body leaks listing: %s", w.Body.String())
217		}
218	
219		// Shape errors win over the device lookup: 400 even for a ghost device.
220		r = httptest.NewRequest(http.MethodGet, "/v1/devices/ghost/attachments?limit=0", nil)
221		w = serveRecorder(h, r)
222		if w.Code != http.StatusBadRequest {
223			t.Fatalf("ghost with bad limit = %d, want 400", w.Code)
224		}
225	
226		// None of the rejections changed the listing.
227		_, items := getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
228		if got := listIDs(items); !equalStrings(got, []string{"att-1"}) {
229			t.Fatalf("list after rejections = %v", got)
230		}
231	}
232	
233	// Empty identifiers, trailing slashes, extra segments and verbs other than
234	// GET on the collection path are all 400 JSON errors — never a redirect or
235	// HTML — and change nothing.
236	func TestListAttachmentsShapeContract(t *testing.T) {
237		h, _ := newTestHandler(t)
238		registerDevice(t, h, "dev-1")
239		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("x"), 1)
240	
241		cases := []struct {
242			method string
243			path   string
244		}{
245			// Empty identifiers and trailing slashes.
246			{http.MethodGet, "/v1/devices//attachments"},
247			{http.MethodGet, "/v1/devices/dev-1/attachments/"},
248			{http.MethodGet, "/v1/devices/dev-1//attachments"},
249			// Extra segments past the collection or item path.
250			{http.MethodGet, "/v1/devices/dev-1/attachments/att-1/extra"},
251			{http.MethodGet, "/v1/devices/dev-1/attachments/att-1/chunks/0/extra"},
252			// Verbs other than GET/POST/DELETE on the collection path.
253			{http.MethodPut, "/v1/devices/dev-1/attachments"},
254			{http.MethodPatch, "/v1/devices/dev-1/attachments"},
255		}
256		for _, tc := range cases {
257			r := httptest.NewRequest(tc.method, tc.path, nil)
258			w := serveRecorder(h, r)
259			if w.Code != http.StatusBadRequest {
260				t.Fatalf("%s %s = %d, want 400", tc.method, tc.path, w.Code)
261			}
262			assertJSONError(t, w)
263			if ct := w.Header().Get("Content-Type"); ct != "application/json" {
264				t.Fatalf("%s %s content-type = %q, want application/json", tc.method, tc.path, ct)
265			}
266		}
267	
268		// Zero writes: the listing is unchanged.
269		_, items := getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
270		if got := listIDs(items); !equalStrings(got, []string{"att-1"}) {
271			t.Fatalf("list after rejected shapes = %v", got)
272		}
273	}
274	
275	// A deleted attachment vanishes from every listing at once — the creator's
276	// and every granted device's — and re-creating the id lists a brand-new
277	// record at the end of the creation order with its progress back to zero.
278	func TestListAttachmentsDeleteAndRecreate(t *testing.T) {
279		h, _ := newTestHandler(t)
280		registerDevice(t, h, "dev-1")
281		registerDevice(t, h, "dev-2")
282		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("hello world"), 4)
283		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
284		mustCreateAttachment(t, h, "dev-1", "att-2", []byte("data"), 2)
285		setAccess(t, h, "dev-1", "att-1", "dev-2", "grant")
286	
287		deleteAttachment(t, h, "dev-1", "att-1")
288	
289		// Gone from the creator's and the granted device's listings at once.
290		_, items := getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
291		if got := listIDs(items); !equalStrings(got, []string{"att-2"}) {
292			t.Fatalf("creator list after delete = %v", got)
293		}
294		w, items := getAttachmentList(t, h, "/v1/devices/dev-2/attachments")
295		if w.Code != http.StatusOK || len(items) != 0 {
296			t.Fatalf("granted list after delete = %d %v", w.Code, items)
297		}
298	
299		// Re-created under the same id: a new record at the end of the order,
300		// with the chunk progress starting from zero again.
301		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("hello world"), 4)
302		_, items = getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
303		if got := listIDs(items); !equalStrings(got, []string{"att-2", "att-1"}) {
304			t.Fatalf("list after recreate = %v, want [att-2 att-1]", got)
305		}
306		if fmt.Sprint(items[1]["receivedChunks"]) != "[]" || items[1]["complete"] != false {
307			t.Fatalf("recreated entry = %v, want zero progress", items[1])
308		}
309		// The old grant was deleted with the record: dev-2 still sees nothing.
310		w, items = getAttachmentList(t, h, "/v1/devices/dev-2/attachments")
311		if w.Code != http.StatusOK || len(items) != 0 {
312			t.Fatalf("granted list after recreate = %d %v", w.Code, items)
313		}
314	}
315	
316	// Revoking a device's read access removes the attachment from its listing at
317	// once; the creator's listing is unaffected.
318	func TestListAttachmentsRevoke(t *testing.T) {
319		h, _ := newTestHandler(t)
320		registerDevice(t, h, "dev-1")
321		registerDevice(t, h, "dev-2")
322		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("hello world"), 4)
323		mustCreateAttachment(t, h, "dev-2", "att-2", []byte("data"), 2)
324		setAccess(t, h, "dev-1", "att-1", "dev-2", "grant")
325	
326		_, items := getAttachmentList(t, h, "/v1/devices/dev-2/attachments")
327		if got := listIDs(items); !equalStrings(got, []string{"att-1", "att-2"}) {
328			t.Fatalf("granted list = %v, want [att-1 att-2]", got)
329		}
330	
331		setAccess(t, h, "dev-1", "att-1", "dev-2", "revoke")
332	
333		_, items = getAttachmentList(t, h, "/v1/devices/dev-2/attachments")
334		if got := listIDs(items); !equalStrings(got, []string{"att-2"}) {
335			t.Fatalf("list after revoke = %v, want [att-2]", got)
336		}
337		_, items = getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
338		if got := listIDs(items); !equalStrings(got, []string{"att-1"}) {
339			t.Fatalf("creator list after revoke = %v, want [att-1]", got)
340		}
341	}
342	
343	// The listing is a read-only view: content, order and pagination are
344	// byte-for-byte identical across a process restart.
345	func TestListAttachmentsSurvivesRestart(t *testing.T) {
346		dbPath := filepath.Join(t.TempDir(), "sync.db")
347		open := func(t *testing.T) (http.Handler, *app.App) {
348			t.Helper()
349			s, err := app.Open(dbPath)
350			if err != nil {
351				t.Fatal(err)
352			}
353			return NewHandler(s), s
354		}
355	
356		h, s := open(t)
357		registerDevice(t, h, "dev-1")
358		registerDevice(t, h, "dev-2")
359		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("hello world"), 4)
360		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
361		mustCreateAttachment(t, h, "dev-2", "att-2", []byte("shared content"), 8)
362		setAccess(t, h, "dev-2", "att-2", "dev-1", "grant")
363	
364		snapshot := func(t *testing.T, h http.Handler) map[string]string {
365			t.Helper()
366			bodies := map[string]string{}
367			for _, url := range []string{
368				"/v1/devices/dev-1/attachments",
369				"/v1/devices/dev-1/attachments?limit=1&offset=0",
370				"/v1/devices/dev-1/attachments?limit=1&offset=1",
371				"/v1/devices/dev-2/attachments",
372			} {
373				r := httptest.NewRequest(http.MethodGet, url, nil)
374				w := serveRecorder(h, r)
375				if w.Code != http.StatusOK {
376					t.Fatalf("GET %s = %d", url, w.Code)
377				}
378				bodies[url] = w.Body.String()
379			}
380			return bodies
381		}
382	
383		before := snapshot(t, h)
384		_ = s.Close()
385	
386		h, s = open(t)
387		defer func() { _ = s.Close() }()
388		after := snapshot(t, h)
389		for url, body := range before {
390			if after[url] != body {
391				t.Fatalf("GET %s after restart = %s, want %s", url, after[url], body)
392			}
393		}
394	}
