30	func TestListAttachments(t *testing.T) {
31		s, err := Open("")
32		if err != nil {
33			t.Fatal(err)
34		}
35		defer func() { _ = s.Close() }()
36		mustRegisterDevice(t, s, "dev-1")
37		mustRegisterDevice(t, s, "dev-2")
38	
39		// Unregistered device: ErrDeviceNotFound, no listing.
40		if _, err := s.ListAttachments("ghost", 100, 0); !errors.Is(err, ErrDeviceNotFound) {
41			t.Fatalf("list on unknown device = %v, want ErrDeviceNotFound", err)
42		}
43	
44		// dev-1 owns att-1 and att-3; dev-2 owns att-2 and grants dev-1 access.
45		for _, tc := range []struct {
46			device, id string
47		}{
48			{"dev-1", "att-1"},
49			{"dev-2", "att-2"},
50			{"dev-1", "att-3"},
51		} {
52			if _, err := s.CreateAttachment(tc.device, toAttachment(tc.id, 4, 2, []byte("data"))); err != nil {
53				t.Fatalf("create %s: %v", tc.id, err)
54			}
55		}
56		if _, err := s.PutChunk("dev-1", "att-1", 1, []byte("ta")); err != nil {
57			t.Fatal(err)
58		}
59		if _, err := s.PutChunk("dev-1", "att-1", 0, []byte("da")); err != nil {
60			t.Fatal(err)
61		}
62		if _, err := s.SetAttachmentAccess("dev-2", "att-2", "dev-1", true); err != nil {
63			t.Fatal(err)
64		}
65		// A grant to the creator itself must not duplicate the entry.
66		if _, err := s.SetAttachmentAccess("dev-1", "att-1", "dev-1", true); err != nil {
67			t.Fatal(err)
68		}
69	
70		items, err := s.ListAttachments("dev-1", 100, 0)
71		if err != nil {
72			t.Fatal(err)
73		}
74		if got := listedIDs(items); !equalIDLists(got, []string{"att-1", "att-2", "att-3"}) {
75			t.Fatalf("list = %v, want [att-1 att-2 att-3]", got)
76		}
77		if !items[0].Owned || items[1].Owned || !items[2].Owned {
78			t.Fatalf("owned flags = %v %v %v", items[0].Owned, items[1].Owned, items[2].Owned)
79		}
80		if got := items[0].ReceivedChunks; len(got) != 2 || got[0] != 0 || got[1] != 1 {
81			t.Fatalf("received chunks = %v, want [0 1]", got)
82		}
83		if len(items[1].ReceivedChunks) != 0 || items[1].ReceivedChunks == nil {
84			t.Fatalf("received chunks = %v, want empty non-nil", items[1].ReceivedChunks)
85		}
