95		}
96		if !equalIDLists(seen, []string{"att-1", "att-2", "att-3"}) {
97			t.Fatalf("paged walk = %v", seen)
98		}
99		page, err := s.ListAttachments("dev-1", 100, 3)
100		if err != nil || len(page) != 0 {
