143	// Databases written before the creation-order column existed are migrated on
144	// open: existing rows keep their insertion order and rows created afterwards
145	// take strictly larger sequence values.
146	func TestListAttachmentsMigratesLegacySchema(t *testing.T) {
147		dbPath := filepath.Join(t.TempDir(), "legacy.db")
148	
149		// Write a database with the pre-migration attachments schema.
150		db, err := sql.Open("sqlite", dbPath+"?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL")
151		if err != nil {
152			t.Fatal(err)
153		}
154		stmts := []string{
155			`CREATE TABLE devices (id TEXT NOT NULL PRIMARY KEY)`,
156			`CREATE TABLE attachments (
157				id          TEXT NOT NULL PRIMARY KEY,
158				device_id   TEXT NOT NULL REFERENCES devices(id),
159				total_bytes INTEGER NOT NULL,
160				chunk_size  INTEGER NOT NULL,
161				sha256      TEXT NOT NULL,
162				complete    INTEGER NOT NULL DEFAULT 0,
163				reused      INTEGER NOT NULL DEFAULT 0
164			)`,
165			`INSERT INTO devices (id) VALUES ('dev-1')`,
166			// Insert out of id order so the backfill must follow insertion order.
167			`INSERT INTO attachments (id, device_id, total_bytes, chunk_size, sha256)
168				VALUES ('att-z', 'dev-1', 4, 2, '` + digestOf([]byte("data")) + `')`,
169			`INSERT INTO attachments (id, device_id, total_bytes, chunk_size, sha256)
170				VALUES ('att-a', 'dev-1', 4, 2, '` + digestOf([]byte("data")) + `')`,
171		}
172		for _, stmt := range stmts {
173			if _, err := db.Exec(stmt); err != nil {
174				t.Fatalf("legacy setup: %v", err)
175			}
176		}
177		if err := db.Close(); err != nil {
178			t.Fatal(err)
179		}
180	
181		s, err := Open(dbPath)
182		if err != nil {
183			t.Fatal(err)
184		}
185		defer func() { _ = s.Close() }()
186	
187		items, err := s.ListAttachments("dev-1", 100, 0)
188		if err != nil {
189			t.Fatal(err)
190		}
191		if got := listedIDs(items); !equalIDLists(got, []string{"att-z", "att-a"}) {
192			t.Fatalf("migrated list = %v, want insertion order [att-z att-a]", got)
193		}
194	
195		// New rows take strictly larger sequence values: they list after every
196		// migrated row, and deleting the newest row never frees a position.
197		if _, err := s.CreateAttachment("dev-1", toAttachment("att-m", 4, 2, []byte("data"))); err != nil {
198			t.Fatal(err)
199		}
200		if err := s.DeleteAttachment("dev-1", "att-m"); err != nil {
201			t.Fatal(err)
202		}
203		if _, err := s.CreateAttachment("dev-1", toAttachment("att-n", 4, 2, []byte("data"))); err != nil {
204			t.Fatal(err)
205		}
