207		if err != nil {
208			t.Fatal(err)
209		}
210		if got := listedIDs(items); !equalIDLists(got, []string{"att-z", "att-a", "att-n"}) {
211			t.Fatalf("list after recreate = %v, want [att-z att-a att-n]", got)
212		}
