// ListAttachmentAccess returns the page of device ids that currently hold
// read access to the attachment, each at most once, ordered by the time their
// latest grant took effect ascending: the grant sequence is assigned one past
// the attachment's maximum inside the granting transaction, so a device
// revoked and re-granted moves to the position of the new grant and never
// appears twice. Only the creator may read the list: an unknown attachment
// yields ErrAttachmentNotFound and a device other than the creator
// ErrAttachmentForbidden, judged independently, and neither writes anything.
// Pagination matches ListAttachments (limit 1..1000, offset non-negative).
// The read runs in one serialized transaction and writes nothing.
func (s *Store) ListAttachmentAccess(callerDeviceID, attachmentID string, limit, offset int64) ([]string, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := loadAttachmentTx(tx, attachmentID)
	if err != nil {
		return nil, err
	}
	if a.DeviceID != callerDeviceID {
		return nil, ErrAttachmentForbidden
	}

	rows, err := tx.Query(
		`SELECT device_id FROM attachment_access
		 WHERE attachment_id = ? AND authorized <> 0
		 ORDER BY granted_seq ASC, device_id ASC
		 LIMIT ? OFFSET ?`,
		attachmentID, limit, offset,
	)

